import{_ as d,o as n,a,b as f}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"附录","link":"/api/appendix/appendix"},{"text":"矩阵计算搬出相关接口边界值汇总","link":"/api/appendix/matrix_compute_move_out_interface_boundary_value_summary"}]},"headers":[],"relativePath":"api/appendix/matrix_compute_move_out_interface_boundary_value_summary.md","filePath":"api/appendix/matrix_compute_move_out_interface_boundary_value_summary.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":3,"title":"数据搬运路径差异","slug":"数据搬运路径差异","link":"#数据搬运路径差异"},{"level":2,"title":"float类型L0C Buffer搬运至各输出类型","slug":"float类型L0C-Buffer搬运至各输出类型","link":"#float类型L0C-Buffer搬运至各输出类型"},{"level":2,"title":"int32_t类型L0C Buffer搬运至各输出类型","slug":"int32_t类型L0C-Buffer搬运至各输出类型","link":"#int32_t类型L0C-Buffer搬运至各输出类型"},{"level":2,"title":"NoQuant（无量化）场景","slug":"NoQuant（无量化）场景","link":"#NoQuant（无量化）场景"}],"lastUpdated":1787971815000}'),i={name:"api/appendix/matrix_compute_move_out_interface_boundary_value_summary.md"};function r(_,t,e,l,F,o){return n(),a("div",null,[...t[0]||(t[0]=[f('<div><article class="markdown-body"><h1>矩阵计算搬出相关接口边界值汇总</h1><p>本节汇总介绍了L0C Buffer-&gt;GM/L0C Buffer-&gt;L1 Buffer/L0C Buffer-&gt;UB搬运接口在L0C Buffer中存在inf/-inf/nan等边界值时的输出结果，涉及接口如下：</p><p><strong>表1</strong> 矩阵计算搬出相关接口说明</p><table><thead><tr><th>搬运路径</th><th>基础API</th><th>C API</th></tr></thead><tbody><tr><td>L0C Buffer-&gt;GM</td><td><a href="../SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe（L0C到GM）</a></td><td><a href="../SIMD-API/c_api/cube_datamove/asc_copy_l0c2gm/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm</a></td></tr><tr><td>L0C Buffer-&gt;L1 Buffer</td><td><a href="../SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/Fixpipe_L0CToL1.html">Fixpipe（L0C到L1）</a></td><td><a href="../SIMD-API/c_api/cube_datamove/asc_copy_l0c2l1/asc_copy_l0c2l1_arch_3510.html">asc_copy_l0c2l1</a></td></tr><tr><td>L0C Buffer-&gt;UB</td><td><a href="../SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/Fixpipe_L0CToUB.html">Fixpipe（L0C到UB）</a></td><td><a href="../SIMD-API/c_api/cube_datamove/asc_copy_l0c2ub.html">asc_copy_l0c2ub</a></td></tr></tbody></table><p>以下内容针对如下型号生效：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>三个搬运指令分别将L0C Buffer中的矩阵计算结果搬运到GM、L1 Buffer和UB，在搬运过程中支持随路量化，将L0C Buffer中的float或int32_t数据转换为目标数据类型输出。随路量化的inf/nan处理行为在三个搬运指令间完全一致，通过基础API <a href="../SIMD-API/basic_api/special_register_access/SetCtrlSpr_ISASI.html">SetCtrlSpr</a> 或 C API <a href="../SIMD-API/c_api/spr/asc_set_ctrl.html">asc_set_ctrl</a> 设置CTRL[48]比特位控制饱和模式：</p><ul><li><strong>饱和模式（CTRL[48]=1&#39;b0）</strong>：inf输出会被饱和为±MAX，nan输出会被饱和为0。</li><li><strong>非饱和模式（CTRL[48]=1&#39;b1）</strong>：inf/nan保持原输出。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li><p>CTRL[48]仅支持如下数据类型的精度转换：half、bfloat16_t、fp8_e4m3fn_t、hifloat8_t。对于float和int32_t数据类型，CTRL[48]不生效，饱和模式与非饱和模式下结果一致。其中float的inf/nan保持原样输出，int32_t不含inf/nan。</p></li><li><p>整数类型（int8_t、uint8_t、int4b_t）只有饱和模式，无论CTRL[48]如何设置，均按饱和模式处理。</p></li><li><p>对于fp8_e4m3fn_t类型，CTRL[50]比特位在饱和模式下进一步控制nan的输出：CTRL[50]=1&#39;b0（默认）时nan被转换为0；CTRL[50]=1&#39;b1时nan保持不变。</p></li></ul></div><h3 id="数据搬运路径差异">数据搬运路径差异<a class="header-anchor" href="#数据搬运路径差异">​</a></h3><p>三个搬运指令的随路量化inf/nan处理行为完全一致，差异仅在验证路径：</p><ul><li><strong>L0C Buffer-&gt;GM</strong>：直接将L0C Buffer数据搬运到GM，无需中转路径，非饱和模式下inf/nan能完整传递到GM输出，无验证路径限制。</li><li><strong>L0C Buffer-&gt;L1 Buffer</strong>：将L0C Buffer数据搬运到L1 Buffer，再通过搬运指令将数据从L1 Buffer搬运至UB，最后从UB搬运到GM。由于L1 Buffer无法直接搬运到GM，此处采用L1-&gt;UB-&gt;GM的中转路径。该路径无二次矩阵计算。</li><li><strong>L0C Buffer-&gt;UB</strong>：将L0C Buffer数据搬运到UB，再从UB搬运到GM。AIC负责L0C Buffer到UB的搬运，AIV负责UB到GM的搬运，通过跨核同步协调。此路径无二次矩阵计算，非饱和模式下inf/nan能完整传递到GM输出。</li></ul><h2 id="float类型L0C-Buffer搬运至各输出类型">float类型L0C Buffer搬运至各输出类型<a class="header-anchor" href="#float类型L0C-Buffer搬运至各输出类型">​</a></h2><p>L0C Buffer中存储的float类型数据来自矩阵乘计算的结果，当输入矩阵A中包含inf/-inf/nan时，L0C Buffer中对应行会出现inf/-inf/nan。</p><p><strong>表2</strong> float类型L0C Buffer中存在inf/-inf/nan时，各输出类型的计算结果说明</p><table><thead><tr><th>输出数据类型</th><th>随路量化模式</th><th>L0C Buffer中的元素取值</th><th>饱和模式输出元素取值</th><th>非饱和模式输出元素取值</th></tr></thead><tbody><tr><td>half</td><td>QF322F16_PRE / VQF322F16_PRE</td><td>+inf</td><td>65504.0（MAX）</td><td>+inf</td></tr><tr><td>half</td><td>QF322F16_PRE / VQF322F16_PRE</td><td>-inf</td><td>-65504.0（MIN）</td><td>-inf</td></tr><tr><td>half</td><td>QF322F16_PRE / VQF322F16_PRE</td><td>nan</td><td>0.0</td><td>nan</td></tr><tr><td>half</td><td>F322F16（Cast）</td><td>+inf</td><td>65504.0（MAX）</td><td>+inf</td></tr><tr><td>half</td><td>F322F16（Cast）</td><td>-inf</td><td>-65504.0（MIN）</td><td>-inf</td></tr><tr><td>half</td><td>F322F16（Cast）</td><td>nan</td><td>0.0</td><td>nan</td></tr><tr><td>bfloat16_t</td><td>QF322BF16_PRE / VQF322BF16_PRE</td><td>+inf</td><td>0x7F7F（MAX）</td><td>0x7F80（+inf）</td></tr><tr><td>bfloat16_t</td><td>QF322BF16_PRE / VQF322BF16_PRE</td><td>-inf</td><td>0xFF7F（MIN）</td><td>0xFF80（-inf）</td></tr><tr><td>bfloat16_t</td><td>QF322BF16_PRE / VQF322BF16_PRE</td><td>nan</td><td>0x0000（0）</td><td>0x7FFF（nan）</td></tr><tr><td>bfloat16_t</td><td>F322BF16（Cast）</td><td>+inf</td><td>0x7F7F（MAX）</td><td>0x7F80（+inf）</td></tr><tr><td>bfloat16_t</td><td>F322BF16（Cast）</td><td>-inf</td><td>0xFF7F（MIN）</td><td>0xFF80（-inf）</td></tr><tr><td>bfloat16_t</td><td>F322BF16（Cast）</td><td>nan</td><td>0x0000（0）</td><td>0x7FFF（nan）</td></tr><tr><td>float</td><td>QF322F32_PRE / VQF322F32_PRE</td><td>+inf</td><td>+inf</td><td>+inf</td></tr><tr><td>float</td><td>QF322F32_PRE / VQF322F32_PRE</td><td>-inf</td><td>-inf</td><td>-inf</td></tr><tr><td>float</td><td>QF322F32_PRE / VQF322F32_PRE</td><td>nan</td><td>nan</td><td>nan</td></tr><tr><td>fp8_e4m3fn_t</td><td>QF322FP8_PRE / VQF322FP8_PRE</td><td>+inf</td><td>0x7E（448.0，MAX）</td><td>0x7F（nan）</td></tr><tr><td>fp8_e4m3fn_t</td><td>QF322FP8_PRE / VQF322FP8_PRE</td><td>-inf</td><td>0xFE（-448.0，MIN）</td><td>0x7F（nan）</td></tr><tr><td>fp8_e4m3fn_t</td><td>QF322FP8_PRE / VQF322FP8_PRE</td><td>nan</td><td>0x00（0）</td><td>0x7F（nan）</td></tr><tr><td>hifloat8_t</td><td>QF322HIF8_PRE / VQF322HIF8_PRE</td><td>+inf</td><td>111（HiF8+inf）</td><td>111（HiF8+inf）</td></tr><tr><td>hifloat8_t</td><td>QF322HIF8_PRE / VQF322HIF8_PRE</td><td>-inf</td><td>239（HiF8-inf）</td><td>239（HiF8-inf）</td></tr><tr><td>hifloat8_t</td><td>QF322HIF8_PRE / VQF322HIF8_PRE</td><td>nan</td><td>0</td><td>128（HiF8NAN）</td></tr><tr><td>hifloat8_t</td><td>QF322HIF8_PRE_HYBRID / VQF322HIF8_PRE_HYBRID</td><td>+inf</td><td>111（HiF8+inf）</td><td>111（HiF8+inf）</td></tr><tr><td>hifloat8_t</td><td>QF322HIF8_PRE_HYBRID / VQF322HIF8_PRE_HYBRID</td><td>-inf</td><td>239（HiF8-inf）</td><td>239（HiF8-inf）</td></tr><tr><td>hifloat8_t</td><td>QF322HIF8_PRE_HYBRID / VQF322HIF8_PRE_HYBRID</td><td>nan</td><td>0</td><td>128（HiF8NAN）</td></tr><tr><td>int8_t</td><td>QF322B8_PRE / VQF322B8_PRE</td><td>+inf</td><td>127（MAX）</td><td>127（MAX）</td></tr><tr><td>int8_t</td><td>QF322B8_PRE / VQF322B8_PRE</td><td>-inf</td><td>-128（MIN）</td><td>-128（MIN）</td></tr><tr><td>int8_t</td><td>QF322B8_PRE / VQF322B8_PRE</td><td>nan</td><td>0</td><td>0</td></tr><tr><td>uint8_t</td><td>QF322B8_PRE / VQF322B8_PRE</td><td>+inf</td><td>255（MAX）</td><td>255（MAX）</td></tr><tr><td>uint8_t</td><td>QF322B8_PRE / VQF322B8_PRE</td><td>-inf</td><td>0（MIN）</td><td>0（MIN）</td></tr><tr><td>uint8_t</td><td>QF322B8_PRE / VQF322B8_PRE</td><td>nan</td><td>0</td><td>0</td></tr><tr><td>int4b_t</td><td>QF322S4_PRE / VQF322S4_PRE</td><td>+inf</td><td>7（MAX）</td><td>7（MAX）</td></tr><tr><td>int4b_t</td><td>QF322S4_PRE / VQF322S4_PRE</td><td>-inf</td><td>-8（MIN）</td><td>-8（MIN）</td></tr><tr><td>int4b_t</td><td>QF322S4_PRE / VQF322S4_PRE</td><td>nan</td><td>0</td><td>0</td></tr></tbody></table><p>注：</p><ul><li>float类型的inf/nan在饱和模式和非饱和模式下均保持原样输出，因为CTRL[48]不支持float数据类型。</li><li>fp8_e4m3fn_t类型没有inf的编码格式。非饱和模式下，若结果绝对值为inf或大于fp8_e4m3fn_t的最大规格化值（448），输出为nan（0x7F）。</li><li>hifloat8_t类型中，111（0b01101111）为HiF8+inf编码，239（0b11101111）为HiF8-inf编码，128（0b10000000）为HiF8NAN编码。饱和模式下，inf保持为对应的inf编码，nan被饱和为0。</li><li>hifloat8_t的溢出判断阈值为1.25×2^15=40960，当量化后的值绝对值大于等于40960时，输出inf编码（111/239），而非饱和为最大值240。</li><li>整数类型只有饱和模式，饱和模式和非饱和模式下的输出结果一致。</li><li>VQF322HIF8_PRE使用Half to Away舍入模式，VQF322HIF8_PRE_HYBRID使用Hybrid舍入模式（|exp|&lt;4时为Half to Away，|exp|≥4时为SSR（Stochastic Rounding）随机舍入）。两种模式对inf/nan的处理一致。</li><li>同一输出类型的scalar模式（如QF322F16_PRE）与tensor模式（如VQF322F16_PRE）使用相同的类型转换算法，inf/nan边界值处理行为完全一致，差异仅在于量化参数的传递方式（单个标量vs每列张量），因此表中将scalar模式与tensor模式合并列出。</li></ul><h2 id="int32_t类型L0C-Buffer搬运至各输出类型">int32_t类型L0C Buffer搬运至各输出类型<a class="header-anchor" href="#int32_t类型L0C-Buffer搬运至各输出类型">​</a></h2><p>L0C Buffer中存储的int32_t类型数据来自矩阵乘计算的结果，不会产生inf/nan，但量化后可能产生溢出。</p><p><strong>表3</strong> int32_t类型L0C Buffer量化溢出时的计算结果说明</p><table><thead><tr><th>输出数据类型</th><th>随路量化模式</th><th>L0C Buffer中的元素取值</th><th>输出元素取值</th></tr></thead><tbody><tr><td>half</td><td>DEQF16 / VDEQF16</td><td>量化后超出half表示范围</td><td>65504.0（MAX） / -65504.0（MIN）</td></tr><tr><td>bfloat16_t</td><td>QS322BF16_PRE / VQS322BF16_PRE</td><td>量化后超出bfloat16表示范围</td><td>0x7F7F（MAX） / 0xFF7F（MIN）</td></tr><tr><td>int8_t</td><td>REQ8 / VREQ8</td><td>量化后大于127</td><td>127（MAX）</td></tr><tr><td>int8_t</td><td>REQ8 / VREQ8</td><td>量化后小于-128</td><td>-128（MIN）</td></tr><tr><td>uint8_t</td><td>REQ8 / VREQ8</td><td>量化后大于255</td><td>255（MAX）</td></tr><tr><td>uint8_t</td><td>REQ8 / VREQ8</td><td>量化后小于0</td><td>0（MIN）</td></tr><tr><td>int4b_t</td><td>REQ4 / VREQ4</td><td>量化后大于7</td><td>7（MAX）</td></tr><tr><td>int4b_t</td><td>REQ4 / VREQ4</td><td>量化后小于-8</td><td>-8（MIN）</td></tr></tbody></table><p>注：整数类型只有饱和模式，溢出时饱和为目标类型的最值。half和bfloat16_t在饱和模式和非饱和模式下均对溢出值进行饱和处理。</p><h2 id="NoQuant（无量化）场景">NoQuant（无量化）场景<a class="header-anchor" href="#NoQuant（无量化）场景">​</a></h2><p>NoQuant模式不做类型转换和量化，L0C Buffer中的float或int32_t数据原样搬运到目标Buffer。CTRL[48]不支持这两种数据类型，饱和模式与非饱和模式下结果一致。float数据可能包含inf/-inf/nan（来自含特殊值的矩阵乘输入），保持原样输出；int32_t为矩阵乘的整数结果，不含inf/nan。NoQuant场景还覆盖了NZ2NZ、NZ2ND、双目标按M维度拆分、双目标按N维度拆分等输出格式，验证float场景下inf/-inf/nan在各种格式转换和双目标拆分中均能正确传递。</p><p><strong>表4</strong> NoQuant模式下float类型L0C Buffer中存在inf/-inf/nan时的输出结果</p><table><thead><tr><th>场景</th><th>输出格式</th><th>双目标</th><th>L0C Buffer中的元素取值</th><th>输出元素取值</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>Nz</td><td>否</td><td>+inf/-inf/nan</td><td>+inf/-inf/nan</td><td>原样保留</td></tr><tr><td>2</td><td>ND</td><td>否</td><td>+inf/-inf/nan</td><td>+inf/-inf/nan</td><td>原样保留</td></tr><tr><td>3</td><td>ND</td><td>是（按M拆分）</td><td>+inf/-inf/nan</td><td>+inf/-inf/nan</td><td>双目标均正确传递</td></tr><tr><td>4</td><td>ND</td><td>是（按N拆分）</td><td>+inf/-inf/nan</td><td>+inf/-inf/nan</td><td>双目标均正确传递</td></tr></tbody></table><p>注：表4仅针对float类型，int32_t不含inf/nan，无需单独验证。场景3按M维度拆分时M需为2的倍数，场景4按N维度拆分时N需为32的倍数。</p></article></div>',1)])])}const p=d(i,[["render",r]]);export{h as __pageData,p as default};
